import XCTest

final class SearchTests: XCTestCase {
    func testSearchRoomForUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let base = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitest/"
        app.coordinate(withNormalizedOffset: CGVector(dx: 0, dy: 0))
            .withOffset(CGVector(dx: 157, dy: 75)).tap()
        sleep(3)
        let row = app.staticTexts["Search room"].firstMatch
        if row.waitForExistence(timeout: 5) { row.tap() } else { app.buttons["Search room"].firstMatch.tap() }
        sleep(3)
        let field = app.searchFields.firstMatch
        if field.waitForExistence(timeout: 5) {
            field.tap()
            field.typeText("update")
            app.keyboards.buttons["Search"].firstMatch.tap()
        } else {
            app.keyboards.buttons["Search"].firstMatch.tap()
        }
        sleep(4)
        try app.debugDescription.write(toFile: base + "dump4.txt", atomically: true, encoding: .utf8)
        try XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: base + "room4.png"))
    }
}
EOF
